(3, 'subtitlemovies', '[{"no":"1","id":"8990","title":"Life | Rated : PG","subtitle":"ch1 | 2024 | Single | PG","slug":"life-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment.\\nSinopsis: Seorang fotografer untuk Majalah LIFE ditugaskan untuk memotret James Dean.","type":"vod","size":"big","image_landscape":["http://pic.dens.tv/poster/files/lands/Life1280x720@3x.jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/Life549x825@3x.jpg"],"trailer_url":""},{"no":"2","id":"8989","title":"Breathe | Rated :PG","subtitle":"ch5 | 2020 | Single | PG","slug":"breathe-rated-pg","description":"Content Rights; PT Cipta Mutu Entertainment (My Family).\\nSinopsis: \\nKisah cinta sejati yang menginspirasi dari Robin dan Diana Cavendish, pasangan petualang yang menolak menyerah di tengah cobaan penyakit yang menghancurkan.","type":"vod","size":"small","image_landscape":["http://pic.dens.tv/poster/files/lands/Breathe1280x720@3x.jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/Breathe549x825@3x.jpg"],"trailer_url":""},{"no":"3","id":"8982","title":"What Children Do | Rated : PG-13","subtitle":"ch2 | 2022 | Single | PG-13","slug":"what-children-do-rated-pg13","description":"Content Rights: ROCK Action.\\nSinopsis: Sebuah komedi tentang dua saudara perempuan yang telah lama berjauhan dan dipertemukan kembali oleh kondisi nenek mereka yang sedang sekarat.","type":"vod","size":"small","image_landscape":["http://pic.dens.tv/poster/files/lands/What-Children-do-landscape-KV1280x720@3x.jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/What-Children-do-portrait-KV549x825@3x.jpg"],"trailer_url":""},{"no":"4","id":"74","title":"Ads Home Mobile 2","slug":"ads-home-mobile-2","description":"","type":"banner_ads","banner_ads_url":"https://picture.dens.tv/wp/img/banner_v1/1008x300/1732616745_banner_v1.jpeg","target":"_self","location":"https://www.dens.tv/movie/watch/8731/office-hour-rated-pg-13-6-episodes/g/1118/sports-and-hobbies","category_content":"vod","content_id":"8731","end_date":"2024-12-31 23:59:59"},{"no":"5","id":"8966","title":"Sponsor (12 Episodes) | Rated : PG-13","subtitle":"ch3 | 2019 | 12 Episodes | PG-13","slug":"sponsor-12-episodes-rated-pg13","description":"Content Rights: K-PLUS.\\nSinopsis: Lee Sun-woo adalah seorang editor dan fotografer. Ia memiliki senyum hangat namun menyembunyikan dahaga untuk balas dendam. Han Chae-rin adalah CEO perusahaan kecantikan. Ia memiliki kekayaan dan kecantikan, tetapi mendambakan cinta. Park Da-som adalah bintang baru yang rela melakukan apa saja demi kesuksesan. Ia berjuang melindungi putranya yang menderita penyakit langka. Suami Da-som, Hyun Seung-hoon, adalah seorang model pemula yang bermimpi meraih kesuksesan.","type":"vod","size":"big","image_landscape":["http://pic.dens.tv/poster/files/lands/EP 1@3x (9).jpg","http://pic.dens.tv/poster/files/lands/EP 2@3x (8).jpg","http://pic.dens.tv/poster/files/lands/EP 3@3x (9).jpg","http://pic.dens.tv/poster/files/lands/EP 4@3x (8).jpg","http://pic.dens.tv/poster/files/lands/EP 5@3x (8).jpg","http://pic.dens.tv/poster/files/lands/EP 6@3x (8).jpg","http://pic.dens.tv/poster/files/lands/EP 7@3x (7).jpg","http://pic.dens.tv/poster/files/lands/EP 8@3x (7).jpg","http://pic.dens.tv/poster/files/lands/EP 9@3x (6).jpg","http://pic.dens.tv/poster/files/lands/EP 10@3x (6).jpg","http://pic.dens.tv/poster/files/lands/EP 11@3x (8).jpg","http://pic.dens.tv/poster/files/lands/EP 12@3x (8).jpg","http://pic.dens.tv/poster/files/lands/Cover@3x (6).jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/EP 1@3x (11).jpg","http://pic.dens.tv/poster/files/port/EP 2@3x (11).jpg","http://pic.dens.tv/poster/files/port/EP 3@3x (11).jpg","http://pic.dens.tv/poster/files/port/EP 4@3x (10).jpg","http://pic.dens.tv/poster/files/port/EP 5@3x (11).jpg","http://pic.dens.tv/poster/files/port/EP 6@3x (9).jpg","http://pic.dens.tv/poster/files/port/EP 7@3x (8).jpg","http://pic.dens.tv/poster/files/port/EP 8@3x (8).jpg","http://pic.dens.tv/poster/files/port/EP 9@3x (6).jpg","http://pic.dens.tv/poster/files/port/EP 10@3x (6).jpg","http://pic.dens.tv/poster/files/port/EP 11@3x (7).jpg","http://pic.dens.tv/poster/files/port/EP 12@3x (11).jpg","http://pic.dens.tv/poster/files/port/Cover@3x (11).jpg"],"trailer_url":""},{"no":"6","id":"8957","title":"Land Shark | Rated : PG-13","subtitle":"ch1 | 2021 | Single | PG-13","slug":"land-shark-rated-pg13","description":"Content Rights: PT Cipta Mutu Entertainment (My Cinema Asia).\\nSinopsis: Qian Cheng, bos perusahaan farmasi, telah berinvestasi dalam sebuah laboratorium penelitian biofarmasi yang terletak jauh di dalam hutan. Mereka memodifikasi gen hiu untuk mengembangkan jenis obat anti-kanker yang baru.","type":"vod","size":"small","image_landscape":["http://pic.dens.tv/poster/files/lands/Land-Shark1280x720@3x.jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/Land-Shark549x825@3x.jpg"],"trailer_url":""},{"no":"7","id":"8946","title":"Rampart | Rated : PG-13","subtitle":"ch2 | 2023 | Single | PG-13","slug":"rampart-rated-pg13","description":"Content Rights: Cipta Mutu Entertainment (My Cinema).\\nSinopsis: Berlatar di Los Angeles tahun 1999, Dave Brown, seorang petugas polisi veteran dan yang terakhir dari para polisi pemberontak, berusaha menjaga keluarganya sekaligus berjuang untuk bertahan hidup.","type":"vod","size":"small","image_landscape":["http://pic.dens.tv/poster/files/lands/Rampart1280x720@3x.jpg"],"image_potrait":["http://pic.dens.tv/poster/files/port/Rampart549x825@3x.jpg"],"trailer_url":""}]', 'homepage', NULL, 'N', '2024-12-19 18:40:33', '2025-04-30 04:51:52', '/top/homemobile/update_section'),
(4, 'sfasa', '[{"no":"1","id":"9389","title":"Framed By My Sister | Rated : PG-13","subtitle":"","slug":"framed-by-my-sister-rated-pg13","description":"Content Rights: ROCK Action.\\nSi kembar Reina dan Alex mendapati hidup mereka kacau akibat kemunculan Trinity, saudari kembar tiga mereka yang terpisah sejak lahir dan kini memiliki rencana misterius: menjebak salah satu dari mereka atas tuduhan pembunuhan dan mengambil alih identitas yang lainnya.","type":"vod","size":"big","image_landscape":["[object Object]"],"image_potrait":["[object Object]"],"trailer_url":""}]', 'homepage', NULL, 'N', '2025-04-30 13:26:23', '2025-04-30 06:26:23', '/top/homemobile/insert_homemobile'),
(5, 'test keywords', '[{"no":"1","id":"9363","title":"Gaus Electronics (12 Episodes) | Rated : PG-13","subtitle":"","slug":"gaus-electronics-12-episodes-rated-pg13","description":"Content Rights: K-PLUS.\\nLee Sang-sik adalah pembuat onar yang tidak peka terhadap suasana hati orang lain. Ia bersikap terus terang bahkan kepada atasannya di tempat kerja. Cha Na-rae adalah seorang asisten manajer yang mudah marah. Baek Ma-tan adalah pewaris perusahaan besar yang bergabung dengan perusahaan dengan impian untuk menjadi mandiri. Gun Gang-mi dikenal karena kecantikannya di kantor, tetapi ketika dia mabuk, dia menunjukkan sisi lain dari dirinya.","type":"vod","size":"big","image_landscape":[{"movie_id":"9365","poster_url":"https://picture.dens.tv/poster/files/lands/EP 1.jpg"},{"movie_id":"9376","poster_url":"https://picture.dens.tv/poster/files/lands/EP 2.jpg"},{"movie_id":"9377","poster_url":"https://picture.dens.tv/poster/files/lands/EP 3.jpg"},{"movie_id":"9378","poster_url":"https://picture.dens.tv/poster/files/lands/EP 4.jpg"},{"movie_id":"9379","poster_url":"https://picture.dens.tv/poster/files/lands/EP 5@3x (11).jpg"},{"movie_id":"9382","poster_url":"https://picture.dens.tv/poster/files/lands/EP 6@3x (11).jpg"},{"movie_id":"9383","poster_url":"https://picture.dens.tv/poster/files/lands/EP 7@3x (10).jpg"},{"movie_id":"9384","poster_url":"https://picture.dens.tv/poster/files/lands/EP 8@3x (10).jpg"},{"movie_id":"9385","poster_url":"https://picture.dens.tv/poster/files/lands/EP 9@3x (9).jpg"},{"movie_id":"9386","poster_url":"https://picture.dens.tv/poster/files/lands/EP 10@3x (9).jpg"},{"movie_id":"9387","poster_url":"https://picture.dens.tv/poster/files/lands/EP 11@3x (10).jpg"},{"movie_id":"9388","poster_url":"https://picture.dens.tv/poster/files/lands/EP 12@3x (10).jpg"},{"movie_id":"9363","poster_url":"https://picture.dens.tv/poster/files/lands/Cover (1).jpg"}],"image_potrait":[{"movie_id":"9365","poster_url":"https://picture.dens.tv/poster/files/port/EP 1@3x (14).j