(6, 'Highlight Video', '[{"no":"1","id":"9380","title":"Nyasar (6 Episodes) | Rated : PG-13","subtitle":"DensFood Channel | 2024 | 6 Episode | PG-13","slug":"nyasar-6-episodes-rated-pg13","description":"Content Rights: DensTV Original Production.\\nNyasar sebuah acara travel food yang menggali dan mengungkap keunikan tersembunyi dari berbagai tempat yang jarang diketahui publik. Setiap episodenya, Kaisha Fridayassie sebagai host Nyasar, akan berkeliling dari satu lokasi ke lokasi lainnya untuk menemukan hidden gems dari sebuah tempat. Dengan latar belakang sebagai seorang chef, Kaisha tentunya mereview sajian dari lokal dan ia mendapatkan pengalaman luar biasa dari tempat yang belum Kaisha kunjungi sebelumnya.","type":"vod","size":"big","image_landscape":[{"movie_id":"9381","poster_url":"https://picture.dens.tv/poster/files/lands/1746501746_land.jpg"},{"movie_id":"9393","poster_url":"https://picture.dens.tv/poster/files/lands/1746004443_land.jpg"},{"movie_id":"9401","poster_url":"https://picture.dens.tv/poster/files/lands/1746766089_land.jpg"},{"movie_id":"9402","poster_url":"https://picture.dens.tv/poster/files/lands/1746766387_land.jpg"},{"movie_id":"9411","poster_url":"https://picture.dens.tv/poster/files/lands/1747381811_land.jpg"},{"movie_id":"9412","poster_url":"https://picture.dens.tv/poster/files/lands/1747381812_land.jpg"},{"movie_id":"9380","poster_url":"https://picture.dens.tv/poster/files/lands/1745930085_land.jpg"}],"image_potrait":[{"movie_id":"9381","poster_url":"https://picture.dens.tv/poster/files/port/1746501562_port.jpg"},{"movie_id":"9393","poster_url":"https://picture.dens.tv/poster/files/port/1746501217_port.jpg"},{"movie_id":"9401","poster_url":"https://picture.dens.tv/poster/files/port/1746765849_port.jpg"},{"movie_id":"9402","poster_url":"https://picture.dens.tv/poster/files/port/1746765850_port.jpg"},{"movie_id":"9411","poster_url":"https://picture.dens.tv/poster/files/port/1747381721_port.jpg"},{"movie_id":"9412","poster_url":"https://pict