(7, 'Animation', '[{"no":"1","id":"1943","title":"Stand by Me Doraemon | Rated : G","slug":"stand-by-me-doraemon-rated-g","description":"Konten ini milik PT. Cipta Mutu Entertainment (My Kidz).\\nSewashi dan Doraemon terlempar jauh ke masa lalu dan bertemu dengan Nobita. Kini, Doraemon harus menjaga Nobita, karena jika tidak, ia tidak akan bisa kembali ke masa kini.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1943","poster_url":"https://picture.dens.tv/poster/files/lands/Stand-by-Me-Doraemon1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"1943","poster_url":"https://picture.dens.tv/poster/files/port/Stand-by-Me-Doraemon549x825@3x.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"1935","keyword_name":"Kids"},{"keyword_id":"4622","keyword_name":"Family"}]},{"no":"2","id":"2194","title":"Alpha and Omega | Rated : PG","slug":"alpha-and-omega-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Dua serigala yang berlawanan dilempar ke negeri yang asing. Mereka saling membutuhkan untuk kembali ke rumah, tetapi cinta memperumit segalanya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2194","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637574943_land.jpg"}],"image_potrait":[{"movie_id":"2194","poster_url":"https://op-picture.dens.tv/poster/files/port/alpha-and-omega549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"1541","title":"Winx Club : The Secret of the Lost Kingdom | Rated : PG","slug":"winx-club-the-secret-of-the-lost-kingdom-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Menceritakan seorang gadis yang mengetahui bahwa dia adalah seorang peri dan putri, gadis itu bernama Bloom.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1541","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637569346_land.jpg"}],"image_potrait":[{"movie_id":"1541","poster_url":"https://op-picture.dens.tv/po