(9, 'Family', '[{"no":"1","id":"1648","title":"Magic Silver 2 | Rated : PG","slug":"magic-silver-2-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Sebuah cerita yang menggambarkan Bluerose sebagai ratu gunung biru yang ingin mendapatkan terompet biru untuk mengubah cuaca buruk. dia bekerja sama dengan raja gunung merah.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1648","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637570816_land.jpg"}],"image_potrait":[{"movie_id":"1648","poster_url":"https://op-picture.dens.tv/poster/files/port/magic-silver-2_549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4572","keyword_name":"Live-Action"}]},{"no":"2","id":"2175","title":"Robo-Dog | Rated : PG","slug":"robodog-rated-pg","description":"Konten ini milik CinemaBOX. Ketika anjing peliharaannya Tyler meninggal secara tragis, Ayahnya, menciptakan seekor robot anjing untuk menggantikannya, lengkap dengan kekuatan mekanik dan kemampuan robot untuk menjaga semua orang.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2175","poster_url":"https://op-picture.dens.tv/poster/files/lands/1556616084_land.jpg"}],"image_potrait":[{"movie_id":"2175","poster_url":"https://op-picture.dens.tv/poster/files/port/robo-dog549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4572","keyword_name":"Live-Action"},{"keyword_id":"4622","keyword_name":"Family"}]},{"no":"3","id":"2527","title":"Journey to the Christmas Star | Rated : G","slug":"journey-to-the-christmas-star-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Seorang gadis pemberani yang melakukan perjalanan berbahaya mencari Christmas Star untuk membebaskan kerajaan dari kutukan dan membawa kembali seorang putri yang telah lama hilang.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2527","poster_url":"https://op-picture.dens.tv/poster/files/lands/1639551693_land.jpg"}],"image_potrait":[{"movie_id":"2527","poster_u