(10, 'Live Action', '[{"no":"1","id":"2177","title":"Pudsey the Dog : The Movie | Rated : PG","slug":"pudsey-the-dog-the-movie-rated-pg","description":"Konten ini milik CinemaBOX. Pudsey The Dog: The Movie bercerita tentang anjing liar London yang nakal, Pudsey, yang senang menjadi penjaga, sampai dia bertemu saudara kandung Molly, George dan Tommy.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2177","poster_url":"https://op-picture.dens.tv/poster/files/lands/1556607710_land.jpg"}],"image_potrait":[{"movie_id":"2177","poster_url":"https://op-picture.dens.tv/poster/files/port/Pudsey-the-Dog-The-Movie549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"1935","keyword_name":"Kids"},{"keyword_id":"4622","keyword_name":"Family"}]},{"no":"2","id":"2215","title":"Arthur 3 : The War of Two Worlds | Rated : PG","slug":"arthur-3-the-war-of-two-worlds-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Pahlawan kita Arthur harus menemukan cara untuk tumbuh kembali ke ukuran normalnya dan menghentikan Evil M untuk selamanya, dengan bantuan Selenia dan Betameche.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2215","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637650578_land.jpg"}],"image_potrait":[{"movie_id":"2215","poster_url":"https://op-picture.dens.tv/poster/files/port/Arthur-3-the-war-of-two-worlds549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"3217","title":"Mr. Go | Rated : PG","slug":"mr-go-rated-pg","description":"Konten ini milik CinemaBOX. Kisah Ling-ling, seekor gorila tua, yang terkenal karena dia bermain baseball di Liga Baseball Korea.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"3217","poster_url":"https://op-picture.dens.tv/poster/files/lands/1597050669_land.jpg"}],"image_potrait":[{"movie_id":"3217","poster_url":"https://op-picture.dens.tv/poster/files/port/1598606907_port.jpg"}],"trailer_url":"","keyw