(11, 'Fantasy', '[{"no":"1","id":"1741","title":"Niko & the Way to the Stars | Rated : G","slug":"niko-the-way-to-the-stars-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Seekor rusa melakukan pencarian untuk menemukan dan menyelamatkan ayahnya, yang dia yakini sebagai anggota Pasukan Terbang Elit Sinterklas yang terkenal di dunia.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1741","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637568398_land.jpg"}],"image_potrait":[{"movie_id":"1741","poster_url":"https://op-picture.dens.tv/poster/files/port/Niko-and-the-way-to-the-stars549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"56","keyword_name":"Comedy"},{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"2193","title":"Sheep & Wolves | Rated : PG","slug":"sheep-wolves-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Gray, seekor serigala ceroboh yang dicari untuk menjadi pemimpin berikutnya. Namun, dia meminum ramuan yang dia terima dari seekor kelinci yang membuatnya harus melindungi koloni domba dari kawanan serigala.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2193","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637573950_land.jpg"}],"image_potrait":[{"movie_id":"2193","poster_url":"https://op-picture.dens.tv/poster/files/port/Sheep-and-wolves549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"2205","title":"Snowflake, the White Gorilla | Rated : PG","slug":"snowflake-the-white-gorilla-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Snowflake adalah satu-satunya gorila putih di dunia, anak-anak menyukainya, karena dia berbeda, tetapi gorila lain tidak. Snowflake keluar dari kebun binatang, untuk menemukan penyihir yang dapat membantunya menjadi gorila \\"normal\\".","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2205","poster_url