(12, 'Science Fiction', '[{"no":"1","id":"9161","title":"Echo | Rated : PG-13","slug":"echo-rated-pg13","description":"Content Rights: Shorts TV.\\nSinopsis: Sebuah drama sci-fi yang mencekam. Seorang kurir sedang mengantarkan sebuah paket, namun dia menemukan bahwa penerimanya berencana merebut kendali atas masyarakat dan masa depan umat manusia.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"9161","poster_url":"https://picture.dens.tv/poster/files/lands/SAA025777_LS.jpg"}],"image_potrait":[{"movie_id":"9161","poster_url":"https://picture.dens.tv/poster/files/port/SAA025777.jpg"}],"trailer_url":"","keywords":null},{"no":"2","id":"1541","title":"Winx Club : The Secret of the Lost Kingdom | Rated : PG","slug":"winx-club-the-secret-of-the-lost-kingdom-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Menceritakan seorang gadis yang mengetahui bahwa dia adalah seorang peri dan putri, gadis itu bernama Bloom.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1541","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637569346_land.jpg"}],"image_potrait":[{"movie_id":"1541","poster_url":"https://op-picture.dens.tv/poster/files/port/Winx-club-the-secret-kingdom549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"3281","title":"Battle for Terra | Rated : PG","slug":"battle-for-terra-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Sebuah planet yang damai menghadapi kehancuran. Mala, seorang remaja pemberontak, akan melakukan apa saja untuk menghentikannya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"3281","poster_url":"https://op-picture.dens.tv/poster/files/lands/1599640600_land.png"}],"image_potrait":[{"movie_id":"3281","poster_url":"https://op-picture.dens.tv/poster/files/port/Battle-for-Terra549x825.png"}],"trailer_url":"","keywords":[{"keyword_id":"8","keyword_name":"Action"},{"keyword_id":"2896","keyword_name":"Action & Adventure"}]}]', 'kids', 5, 'Y', '2025-07-07 11:10:08', '2025-07-07 04:57:29', '/kids/kids/activated_kids'),
(13, 'Adventure', '[{"no":"1","id":"8950","title":"The Snow Queen & the Princess | Rated : PG","slug":"the-snow-queen-the-princess-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Kidz).\\nSinopsis: Kai dan Gerda tinggal di sebuah kota kecil yang tenang, ketika tiba-tiba Roh Es datang untuk membekukan semua orang. Namun, Ila, seorang penyihir kecil, datang untuk membantu para pahlawan. Bersama-sama, mereka pergi ke dunia ajaib Mirrorland untuk mengembalikan Roh Es.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"8950","poster_url":"https://picture.dens.tv/poster/files/lands/The-Snow-Queen-and-the-Princess1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"8950","poster_url":"https://picture.dens.tv/poster/files/port/The-Snow-Queen-and-the-Princess549x825@3x.jpg"}],"trailer_url":"","keywords":null},{"no":"2","id":"8949","title":"Red Shoes and the 7th Dwarfs | Rated : PG","slug":"red-shoes-and-the-7th-dwarfs-rated-pg","description":"Content Rights: PT Cipta Mutu  Entertainment (My Kidz).\\nSinopsis: Para pangeran yang telah diubah menjadi kurcaci mencari sepatu merah milik seorang wanita untuk mematahkan kutukan, meskipun itu tidak akan mudah. Sebuah parodi dengan sentuhan yang tak terduga.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"8949","poster_url":"https://picture.dens.tv/poster/files/lands/Red-Shoes-and-the-Seven-Dwarfs1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"8949","poster_url":"https://picture.dens.tv/poster/files/port/Red-Shoes-and-the-Seven-Dwarfs549x825@3x.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"3522","keyword_name":"Comedy Family"}]},{"no":"3","id":"8948","title":"Manou the Swift | Rated : Not Rated","slug":"manou-the-swift-rated-not-rated","description":"Content Rights: PT Cipta Mutu Entertainmen (My Kidz).\\nSinopsis: Manou, seekor burung kecil yang tumbuh dengan keyakinan bahwa dia adalah seekor camar, belajar terbang hanya untuk menemukan bahwa dia tidak akan pernah bisa. Ketika dia melarikan diri dari rumah, dia bertemu dengan burung-burung dari spesiesnya sendiri dan akhirnya mengetahui siapa dirinya sebenarnya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"8948","poster_url":"https://picture.dens.tv/poster/files/lands/Manou-the-Swift1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"8948","poster_url":"https://picture.dens.tv/poster/files/port/Manou-the-Swift549x825@3x.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"3522","keyword_name":"Comedy Family"}]}]', 'kids', 6, 'Y', '2025-07-07 11:11:00', '2025-07-07 04:58:10', '/kids/kids/activated_kids'),
