(15, 'Animal / Talking Animals', '[{"no":"1","id":"1544","title":"Niko 2 : Little Brother, Big Trouble | Rated : G","slug":"niko-2-little-brother-big-trouble-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Terjadi tepat sebelum Natal, Niko si rusa harus berurusan dengan ibunya yang menikah kembali dan dia ditugaskan untuk menjaga adik tirinya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1544","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637567798_land.jpg"}],"image_potrait":[{"movie_id":"1544","poster_url":"https://op-picture.dens.tv/poster/files/port/niko-2_549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"56","keyword_name":"Comedy"},{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"1552","title":"Marco Macaco | Rated : PG","slug":"marco-macaco-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Marco adalah polisi yang memecahkan kejahatan besar; pada kenyataannya, dia adalah petugas pantai yang berdedikasi di sebuah pulau tropis. Dia mendapat kesempatan untuk menjadi pahlawan ketika dia mengungkap rencana kejahatan besar.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1552","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637566313_land.jpg"}],"image_potrait":[{"movie_id":"1552","poster_url":"https://op-picture.dens.tv/poster/files/port/marco-macaco549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"1747","title":"Pororo : The Racing Adventure | Rated : G","slug":"pororo-the-racing-adventure-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Pororo, seekor penguin kecil secara tidak sengaja menyebabkan sebuah pesawat melakukan pendaratan darurat di desanya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1747","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637571170_land.jpg"}],"image_potrait":[{"movie_id":"1747","pos