(16, 'Fairy Tale', '[{"no":"1","id":"1550","title":"The 7th Dwarf | Rated : PG","slug":"the-7th-dwarf-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). The 7th Dwarf adalah film animasi Jerman, yang dibuat berdasarkan dongeng Sleeping Beauty, juga karakter dari Snow White dan Tujuh Kurcaci.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1550","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637659686_land.jpg"}],"image_potrait":[{"movie_id":"1550","poster_url":"https://op-picture.dens.tv/poster/files/port/the-7th-dwarf549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"56","keyword_name":"Comedy"},{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"8489","title":"Mune Guardian of The Moon | Rated : PG","slug":"mune-guardian-of-the-moon-rated-pg","description":"Content Rights: PT Cipta Mutu Entertainment (My Cinema).\\nSinopsis: Mune, seekor rusa muda, dipilih sebagai Penjaga Bulan baru. Bersama dengan Glim, seorang gadis yang terbuat dari lilin, dan Sohone, Penjaga Matahari baru, mereka harus mengembalikan matahari dari Necross yang jahat.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"8489","poster_url":"https://picture.dens.tv/poster/files/lands/Mune-Guardian-of-the-Moon1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"8489","poster_url":"https://picture.dens.tv/poster/files/port/Mune-Guardian-of-the-Moon549x825@3x.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"3486","keyword_name":"Comedy Adventure"}]},{"no":"3","id":"2207","title":"Arthur and the Revenge of Maltazard | Rated : PG","slug":"arthur-and-the-revenge-of-maltazard-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Ketika Arthur mengungkap panggilan darurat yang dikirim dari Minimoys, dia harus memulai petualangan besar untuk berperang melawan Maltazard dan menyelamatkan Putri Selenia.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2207","poster_url":"https://op-picture.dens