(17, 'Animation Musical', '[{"no":"1","id":"2883","title":"Rock Dog | Rated : PG","slug":"rock-dog-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Ketika sebuah radio jatuh dari langit ke tangan Tibetan Mastiff, dia meninggalkan rumah untuk memenuhi mimpinya menjadi seorang musisi.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2883","poster_url":"https://op-picture.dens.tv/poster/files/lands/1570781447_land.jpg"}],"image_potrait":[{"movie_id":"2883","poster_url":"https://op-picture.dens.tv/poster/files/port/Rock-Dog549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"1746","title":"Plumiferos (Free Birds) | Rated : G","slug":"plumiferos-free-birds-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Menceritakan kisah tentang seekor burung pipit yang mengubah penampilannya dan seekor kenari yang melarikan diri dari kandangnya. Dua kisah yang merupakan bagian dari kumpulan cerita tentang burung.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1746","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637659702_land.jpg"}],"image_potrait":[{"movie_id":"1746","poster_url":"https://op-picture.dens.tv/poster/files/port/Plumiferos549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"1552","title":"Marco Macaco | Rated : PG","slug":"marco-macaco-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Marco adalah polisi yang memecahkan kejahatan besar; pada kenyataannya, dia adalah petugas pantai yang berdedikasi di sebuah pulau tropis. Dia mendapat kesempatan untuk menjadi pahlawan ketika dia mengungkap rencana kejahatan besar.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1552","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637566313_land.jpg"}],"image_potrait":[{"movie_id":"1552","poster_url":"https://op-picture.dens.tv/p