(18, 'Sport', '[{"no":"1","id":"2199","title":"Legend of a Rabbit : The Martial of Fire | Rated : PG","slug":"legend-of-a-rabbit-the-martial-of-fire-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Fu sekarang dianggap sebagai pelindung desa, mengalahkan bandit dan menegakkan keadilan. Namun tanpa keterampilan, Fu harus memulai pelatihan untuk memanfaatkan kungfu warisan grand master.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2199","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637648548_land.jpg"}],"image_potrait":[{"movie_id":"2199","poster_url":"https://op-picture.dens.tv/poster/files/port/Legend-of-Rabbit-2_549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"1747","title":"Pororo : The Racing Adventure | Rated : G","slug":"pororo-the-racing-adventure-rated-g","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Pororo, seekor penguin kecil secara tidak sengaja menyebabkan sebuah pesawat melakukan pendaratan darurat di desanya.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"1747","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637571170_land.jpg"}],"image_potrait":[{"movie_id":"1747","poster_url":"https://op-picture.dens.tv/poster/files/port/Pororo-Racing-Adventure549x825.jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"3","id":"2706","title":"Early Man | Rated : PG","slug":"early-man-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Film ini bercerita tentang suku penghuni lembah Zaman Batu primitif, yang harus mempertahankan tanah mereka dari penjajah.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2706","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637655464_land.jpg"}],"image_potrait":[{"movie_id":"2706","poster_url":"https://op-picture.dens.tv/poster/files/port/Early-Man549x825 (1).jpg"}],"trailer_url