(19, 'Computer Animation', '[{"no":"1","id":"2216","title":"Norm of the North | Rated : PG","slug":"norm-of-the-north-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Tergusur dari rumah mereka, seekor beruang kutub bernama Norm dan ketiga temannya berada di New York City, di mana Norm menjadi maskot sebuah perusahaan.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"2216","poster_url":"https://op-picture.dens.tv/poster/files/lands/1637650913_land.jpg"}],"image_potrait":[{"movie_id":"2216","poster_url":"https://op-picture.dens.tv/poster/files/port/norm-of-the-north549x825 (1).jpg"}],"trailer_url":"","keywords":[{"keyword_id":"4664","keyword_name":"Animation"}]},{"no":"2","id":"8261","title":"Monster Family 2 | Rated : PG","slug":"monster-family-2-rated-pg","description":"Content Rights: Cipta Mutu Entertainment (My Cinema).\\nSinopsis: Untuk membebaskan Baba Yaga dan Renfield dari cengkeraman Monster Hunter Mila Starr, Keluarga Wishbone sekali lagi berubah menjadi seorang Vampir, Monster Frankenstein, seorang Mumia, dan seorang Werewolf.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"8261","poster_url":"https://picture.dens.tv/poster/files/lands/Monster-Family2_1280x720@3x.jpg"}],"image_potrait":[{"movie_id":"8261","poster_url":"https://picture.dens.tv/poster/files/port/Monster-Family2_549x825@3x.jpg"}],"trailer_url":"","keywords":null},{"no":"3","id":"3283","title":"Dragon Hunters | Rated : PG","slug":"dragon-hunters-rated-pg","description":"Konten ini milik Cipta Mutu Entertainment (My Kidz). Kerajaan fantasi berada di bawah ancaman naga mengerikan yang kembali mengganggu mereka setiap 20 tahun.","subtitle":"","type":"vod","image_landscape":[{"movie_id":"3283","poster_url":"https://op-picture.dens.tv/poster/files/lands/1599640592_land.png"}],"image_potrait":[{"movie_id":"3283","poster_url":"https://op-picture.dens.tv/poster/files/port/Dragon-Hunters549x825.png"}],"trailer_url":"","keywords":[{"keyword_id":"4664"